import Service from '#class/service';
import type { ChangeToken, CommunicatieId, Document, DocumentId, DocUploadBody, PolisId, PostResponse, RowRes, Validator } from '#types';
import assert from 'assert';
import fs from 'fs';

/**
 * Operaties op documenten van een polis in Axon: uploaden en opzoeken van
 * hun changeToken (nodig om een document later als bijlage te koppelen).
 */
export default class DocumentenService extends Service {

    /** Uploadt een document naar een polis in Axon vanaf een bestand op schijf. */
    async uploadFromPath(polisnummer: PolisId, path: string, options: Omit<DocUploadBody, 'contents'>) {
        const contents = fs.readFileSync(path, { encoding: "base64" });
        return await this.uploadFromBuffer(polisnummer, { ...options, contents });
    }

    /** Uploadt een document naar een polis in Axon vanaf base64-gecodeerde inhoud. */
    async uploadFromBuffer(polisnummer: PolisId, payload: DocUploadBody) {
        assert(payload.contents, "Encoded file content not found");
        const restUrl = `policy/${polisnummer}/documents`;
        const options = { ...payload, documentTypeExternalIdentifier: "externalDocument" };
        return await this.session.postAxon<PostResponse<DocumentId>>(restUrl, options);
    }

    /** Retourneert alle documenten die behoren tot het polisnummer en zijn ontstaan door upload. */
    async getUploadedFromPolis(polisnummer: PolisId): Promise<Document[]>;
    /** Retourneert alle documenten die behoren tot het polisnummer, zijn ontstaan door upload en voldoen aan `isValid`. */
    async getUploadedFromPolis(polisnummer: PolisId, isValid: Validator<Document>): Promise<Document[]>;
    /** Retourneert alle documenten die behoren tot het polisnummer, zijn ontstaan door upload en voldoen aan `isValid`. */
    async getUploadedFromPolis(polisnummer: PolisId, isValid: Validator<Document>, returnOnlyOne: false): Promise<Document[]>;
    /** Retourneert het eerste gevonden document die behoort tot het polisnummer, zijn ontstaan door upload en voldoet aan `isValid`. */
    async getUploadedFromPolis(polisnummer: PolisId, isValid: Validator<Document>, returnOnlyOne: true): Promise<Document>;
    async getUploadedFromPolis(polisnummer: PolisId, isValid: Validator<Document> = () => true, exactlyOne: boolean = false) {
        const url = `policy/${polisnummer}/documents/search/overview`;
        const res = await this.session.getAxon<RowRes<Document>>(
            url,
            { documentCategoryExtId: "externalDocument", originatedViaExtId: "upload" }
        );
        const docs = res.rows.filter(isValid);
        if (!exactlyOne) return docs;
        assert(docs.length === 1, `${docs.length} documenten gevonden voor polis ${polisnummer}, had 1 verwacht.`);
        return docs[0];
    }

    /**
     * Zoekt het changeToken van een geüpload document op, nodig om het
     * document als bijlage aan een communicatie te koppelen.
     * @param docId externalIdentifier van het document.
     */
    async getChangeToken(polisnummer: PolisId, docId: DocumentId) {
        const validator = (doc: Document) => doc.externalIdentifier === docId;
        const doc = await this.getUploadedFromPolis(polisnummer, validator, true);
        assert(doc.changeToken, `Document ${docId} voor polis ${polisnummer} heeft geen changeToken.`);
        return doc.changeToken;
    }

    async koppelAanCommunicatie(comId: CommunicatieId, docId: DocumentId, changeToken: ChangeToken) {
        const restUrl = `policy-communications/${comId}/attach-existing-documents`;
        const options = [{ externalIdentifier: docId, changeToken }];
        return this.session.postAxon<PostResponse>(restUrl, options);
    }
}
